11	} from "react";
12	import { MarketingButton } from "../../components/marketing-button";
13	import { LivePanel } from "../live-panel";
14	import { LOCKED_LOOK } from "../locked-look";
15	import { StableStack } from "../stable-stack";
16	import { ViewSwitch } from "../view-switch";
17	import { rebakeShell } from "./actions";
18	import {
19	  CAPTION_VARIANTS,
20	  DETAIL_VARIANTS,
21	  REBAKE_FAILED_CAPTION,
22	  readout,
23	  SETTLING_READOUT,
24	} from "./rebake-copy";
25	import {
26	  canFetch,
27	  canRebake,
28	  INITIAL_REBAKE_STATE,
29	  rebakeReducer,
30	} from "./rebake-state";
31	
32	const FUSED_LABELS = ["Revalidate this page", "Revalidating…"];
33	const EXPIRE_LABELS = ["Expire the entry", "Expiring…"];
34	const ASK_LABELS = ["Ask for the page", "Asking…"];
35	
36	/** The mono step marker inside a deck button — real sequence, so real numbers. */
37	function StepMark({ n }: { n: string }) {
38	  return (
39	    <span
40	      aria-hidden="true"
41	      className="mr-2 select-none font-mono text-muted-foreground text-xs"
