async function GroupRows({ run, strategy }: RunProps) {
  await connection();
  const startedAt = Date.now();
  await Promise.all(STREAM_ROWS.map((row) => sleep(row.delayMs)));
  const landedMs = Date.now() - startedAt;

  return (
    <>
      {STREAM_ROWS.map((row) => (
        <LandedRow
          delayMs={row.delayMs}
          key={row.label}
          label={row.label}
          landedMs={landedMs}
          short={row.short}
        />
      ))}
      <StageSettled run={run} strategy={strategy} />
    </>
  );
